from assessment_writer import write_review
def compact(sid,title,rows,appraisal):
    write_review(sid,title,[(a,b.split(' | '),c) for a,b,c in rows],appraisal)

compact('OWEN-2000','Complex I experiments: a proposed mechanism with exposure and model limits',[
('Introduction; Experimental','Test whether complex I inhibition explains metformin effects on gluconeogenesis. | NR: No preregistered protocol reported. | Mitochondrial respiration and liver metabolites.','Not a trial of repurposed clinical efficacy.'),
('Experimental; Figures 1–6','Male Wistar rats, rat H4IIE hepatoma cells and isolated mitochondria/particles. | Rats 250–300 g; hepatocytes/liver mitochondria often from fasted animals. | Typically three independent preparations; four livers per metabolite group; other assays report separate n.','No human participants.'),
('Experimental','Sigma metformin; phenformin comparison. | Cells 50/100 µM for 24/60 h; isolated preparations millimolar doses; rats 50/150 mg per rat daily five days. | Substrate, ADP and glucagon manipulations; digitonin permeabilization. | Minutes/hours in isolated assays, five-day animal exposure.','Per-rat doses are not human doses.'),
('Experimental; figure legends','No-drug/water controls and alternative mitochondrial substrates. | Preparation-level paired comparisons where stated. | NR: Animal allocation randomization not reported. | NR: Blinding not reported. | Time- and concentration-dependent comparisons.','Mechanistic controls improve specificity but do not establish clinical transportability.'),
('Figures 1–6','Respiration, NADH oxidation, glucose production and metabolite ratios. | Oxygen electrode, spectrophotometry and metabolite assays. | Assay-dependent timepoints. | Biochemical outcomes, not patient outcomes. | NA: No human MCID.','Calculated free ATP/ADP differs from measured total nucleotide levels.'),
('Figure 1; Results','50 µM metformin inhibited glutamate/malate oxidation by 12.6±4.3% at 24 h and 29.4±7.7% at 60 h. | Figure-specific independent preparations; control cell oxidation n=18 glutamate/malate and n=15 succinate. | Mean±SEM; succinate oxidation unaffected. | Submitochondrial particles required about 79 mM for half inhibition. | No clinical CI; paired/unpaired t-tests by experiment.','Different membrane preparations require very different exposures.'),
('Experimental; figures','NR: Animal attrition not tabulated. | NR: Missing experiments and exclusions not fully documented. | Oral dosing stated; no direct plasma-exposure measurement for every study group. | Isolation changes membrane permeability and may lose accumulated drug. | Independent preparations or animals by assay. | Biological preparation/animal, not repeated instrument readings.','Assay artifacts are discussed by the authors.'),
('Animal treatment','Visible distress and body weight observed. | Small short-duration rat groups. | No visible distress or significant mean weight effect reported. | NR: Toxicity-related withdrawals not reported. | Five days.','Not a human safety assessment.'),
('Discussion','Small mechanistic experiments, unclear allocation/masking and isolation artifacts. | Substrate controls distinguish respiratory-chain sites; other cellular actions remain possible. | NR: No preregistered endpoint hierarchy. | Numerous biochemical comparisons. | Limited biological n and no human clinical estimate. | Free ATP/ADP values are calculated; total ATP was not significantly changed.','Do not present calculated energetic changes as directly measured human effects.'),
('Discussion','Rat liver/cell biology. | Some cell exposures micromolar, many isolated assays millimolar; human liver accumulation inferred. | Supports a complex-I mechanism hypothesis. | Does not prove it is the sole mechanism, or demonstrate cancer, infection or longevity benefit.','Model/exposure boundaries are central.'),
('Article discussion','Owen, Doran and Halestrap experimental program. | El-Mir 2000 cited as a related independent report with a different direct/indirect interpretation. | Multiple preparations within this paper are not separate clinical trials. | Scoped mechanism sources, not exhaustive mechanistic review.','The unacquired El-Mir full text is not silently counted as assessed.'),
('Byline; acknowledgments','Mark R. Owen, Elena Doran and Andrew P. Halestrap. | University of Bristol biochemistry. | British Diabetic Association. | Commercial Sigma reagents. | NR: No modern structured competing-interest declaration located.','Absence of a declaration is not a declaration of no conflicts.'),
('Full PDF','Biochemical Journal 2000;348:607–614. | Complete publisher-formatted PDF recovered from a public mirror and title/authors/pages verified. | No separate supplement relied upon. | NA: Nonclinical study; Home Office animal compliance stated. | No correction/retraction identified in retrieved records. | November 4, 2026.','Mirror provenance retained with SHA-256.'),
('G-METFORMIN mechanisms','Cellular energy and complex I. | Indirect mechanistic support. | Observed substrate-specific inhibition; authors infer mitochondrial accumulation and clinical relevance.','No repurposing benefit follows automatically.'),
('Synthesis','Complex I inhibition is one experimentally supported proposed mechanism. | Relative contribution in human tissues at ordinary exposure remains a separate question. | Human target-engagement and outcome studies needed for clinical claims.','No dose recommendation.')
], 'Substrate-specific and concentration/time-dependent experiments support a complex-I hypothesis. Isolation artifacts, high assay concentrations and small nonhuman samples limit extrapolation; clinical repurposing efficacy is not tested.')

compact('MF-COLON-MECHANISM-2010','Colorectal crypt-foci pilot: within-group results and an unvalidated clinical surrogate',[
('p1077–1078','Test low-dose metformin effects on rectal aberrant crypt foci. | One-month pilot, registry UMIN000001241 identified. | Crypt-foci counts and epithelial proliferation.','Not colorectal cancer incidence.'),
('p1078–1080','Nondiabetic adults with endoscopically identified crypt foci. | Yokohama City University; major hepatic/renal disease, pregnancy, CRC and NSAIDs excluded. | 1342 screened, 629 with foci, 26 randomized: 12 metformin/14 untreated; 9/14 analyzed.','Very selected and predominantly male sample.'),
('p1078','Metformin, formulation/product not specified in the inspected pages. | Oral 250 mg/day for one month. | Prior screening/polypectomy when needed. | One month.','Not a recommended chemoprevention schedule.'),
('p1078–1079','No treatment, not placebo. | Participants assigned to two groups. | Randomization stated; sequence/concealment not described. | Endoscopic and laboratory assessments masked; participants not placebo-blinded. | Baseline and one-month comparison.','Lack of placebo and allocation detail increase uncertainty.'),
('p1079–1080','Crypt-foci count; PCNA proliferation and TUNEL apoptosis. | Magnifying colonoscopy with methylene blue; two masked observers; biopsies. | Baseline to one month. | Surrogate lesion and cellular markers. | NR: No established cancer-risk reduction threshold.','No cancer endpoint.'),
('p1077; Table 2; Figure 2','Metformin foci 8.78±6.45 to 5.11±4.99; control 7.23±6.65 to 7.56±6.75. | Nine metformin and fourteen control analyzed. | Mean±SD foci per participant. | Metformin within-arm P=.007; control within-arm P=.609. | NR: No reported between-group change estimate with CI.','Significant in one arm and nonsignificant in another does not establish a significant treatment interaction.'),
('p1080','Three of twelve metformin participants lacked endpoint: one stopped early, two refused colonoscopy. | All missing endpoints in the metformin arm. | NR: Pill adherence not quantified. | Complete-case exclusion of three metformin participants. | 23 evaluable participants. | Participant, not crypt count or microscopic field.','Biopsy fields are technical observations.'),
('p1081 Drug safety','Brief safety narrative without detailed surveillance methods. | Twelve assigned, nine evaluable metformin participants; safety denominator not explicit. | No side effects reported, including diarrhea, hypoglycemia or lactic acidosis. | One early treatment stop; cause not stated. | One month.','Cannot infer long-term or rare-event safety.'),
('p1080–1082','Tiny sample, one-arm missingness, no placebo and within-arm testing. | Randomization not described sufficiently to exclude selection bias. | GAP: Registry history and supplementary Figure S1 not recovered. | Several foci categories and laboratory tests. | No between-group CI; substantial uncertainty. | Control age SD printed 90.7 years, evidently discordant with the scale; not silently repaired.','No causal effect size calculated from these data.'),
('p1082','Selected nondiabetic adults with crypt foci. | 250 mg daily for one month. | Preliminary surrogate signal only. | Does not establish prevention of adenomas or cancer, or effect in average-risk adults.','Later adenoma trial is a different study and endpoint.'),
('Registry and byline','Hosono 2010 human pilot, UMIN000001241. | Related animal studies and Higurashi 2016 adenoma trial. | Distinct from animal experiments in the same research program. | Current inventory reconciliation.','Do not mistake the adjacent leptin paper in the archive for this study.'),
('p1077; p1082','Kunihiro Hosono, Hiroki Endo, Hirokazu Takahashi and colleagues; Atsushi Nakajima corresponding. | Yokohama City University and National Cancer Center Japan. | Japanese ministry, biomedical innovation, Yokohama foundation and JST grants. | NR: Metformin supplier not stated in inspected pages. | No potential conflicts disclosed.','Funding/COI located on p1082, not the unrelated preceding article.'),
('Archive PDF pp5–10','Cancer Prevention Research 2010;3:1077–1083, DOI 10.1158/1940-6207.CAPR-10-0186. | Relevant pp1077–1082 visually read in mixed grant archive. | GAP: Final reference page1083 and supplementary Figure S1 absent. | UMIN000001241 stated, separate record not audited. | No correction/retraction identified in retrieved records. | November 4, 2026.','Readable images used because embedded text extraction was empty.'),
('G-METFORMIN colorectal section','Early human mechanistic pilot. | Indirect rationale, not clinical prevention proof. | Authors infer promise; guide emphasizes within-group analysis and surrogate endpoint.','Never cite as a positive cancer-prevention trial.'),
('Synthesis','Small preliminary foci changes motivated further research. | Controlled change magnitude and long-term cancer relevance remain unknown. | Larger randomized between-group clinical-outcome evidence required.','The 2016 lesion trial adds evidence but still does not prove reduced cancer mortality.')
], 'A small unblinded pilot with blinded assessment, substantial metformin-arm attrition and within-group hypothesis tests. It supplies preliminary biological context, not a reliable between-group cancer-prevention effect.')
